type ChatThreadLoadState = {
  status: 'resolving' | 'loading' | 'ready' | 'error';
  threadId: string | null;
  message?: string;
};

function activeChatThreadStorageKey(circleId: string, userId?: string | null): string {
  const safeCircleId = String(circleId || '').trim().slice(0, 160) || '_';
  const safeUserId = String(userId || '').trim().slice(0, 160) || '_';
  return `uc_chat_active_thread::${safeCircleId}::${safeUserId}`;
}

function transcriptChatMessages(messages: ChatMessage[]): ChatMessage[] {
  return messages.filter((message) => message.durability !== 'ephemeral');
}

const LEGACY_EPHEMERAL_CHAT_SURFACES = new Set([
  'main_chat_multi_intent_notice',
  'main_chat_session_greeting',
  'chat_automation_suggestion',
  'chat_agent_selector_setup',
  'agent_plan_mode_help',
  'multi_agent_dispatch',
  'multi_agent_roundtable',
  'multi_agent_chain',
  'multi_agent_debate',
  'multi_agent_help',
]);

function isLegacyEphemeralChatSurface(surface?: string | null): boolean {
  return LEGACY_EPHEMERAL_CHAT_SURFACES.has(String(surface || '').trim());
}

type PlainChatFailurePresentation = {
  message: string;
  quickReplies: string[];
  quickRepliesLabel?: string;
};

function buildPlainChatFailurePresentation(
  error: unknown,
  modelLabel: string,
): PlainChatFailurePresentation {
  const credentialRecovery = error instanceof LLMProxyInvocationError
    ? getLLMProxyCredentialRecoveryPresentation(error)
    : null;
  if (credentialRecovery) {
    return {
      message: credentialRecovery.message,
      quickReplies: [credentialRecovery.actionLabel],
      quickRepliesLabel: 'Fix model connection',
    };
  }
  return {
    message: `I couldn't reach ${modelLabel} for that reply. Try again in a moment or choose another model.`,
    quickReplies: ['Try again'],
  };
}

function resolveMarketplaceCredentialAction(reply: string): {
  handled: boolean;
  itemId: string | null;
} {
  const match = /^(?:connect|reconnect)\s+(.+)$/i.exec(String(reply || '').trim());
  if (!match) return { handled: false, itemId: null };
  const itemByLabel: Record<string, string> = {
    anthropic: 'anthropic',
    openai: 'openai',
    openrouter: 'openrouter',
    groq: 'groq',
    'google ai': 'google_ai',
    'mistral ai': 'mistral_ai',
    cohere: 'cohere',
    perplexity: 'perplexity',
    'together ai': 'together_ai',
    'fireworks ai': 'fireworks_ai',
    deepseek: 'deepseek',
    'hugging face': 'hugging_face',
    'z.ai': 'z_ai',
    minimax: 'minimax',
    replicate: 'replicate',
  };
  return {
    handled: true,
    itemId: itemByLabel[match[1].trim().toLowerCase()] || null,
  };
}

function shortenAddress(address: string | null | undefined): string {
  const value = String(address || '');
  if (value.length <= 12) return value;
  return `${value.slice(0, 6)}...${value.slice(-4)}`;
}
type AssignableAgent = {
  id: string;
  name: string;
  status: string;
  provider: string;
  ownerId?: string | null;
  isOwn?: boolean;
  color?: string | null;
  owner_display_name?: string | null;
  current_task?: string | null;
  circle_id?: string | null;
  spirit?: string | null;
  model?: string | null;
  sessionKey?: string | null;
  connectionId?: string | null;
  gatewayUrl?: string | null;
  source?: 'db' | 'openswan-session' | 'bridge-session' | 'default';
  terminalConfig?: TerminalAgentOfficeConfig | null;
};

function applyTerminalProfileToTask(task: string, config?: TerminalAgentOfficeConfig | null): string {
  const instructions = config?.defaultPrompt?.trim();
  if (!instructions) return task;
  return [
    instructions,
    '',
    'Task from The Underground Circle chat:',
    task,
  ].join('\n');
}

function parseAgentExtendedConfig(raw: string | null | undefined): Record<string, any> | null {
  if (!raw) return null;
  try {
    const parsed = JSON.parse(raw);
    return parsed && typeof parsed === 'object' ? parsed : null;
  } catch {
    return null;
  }
}

function toAssignableDbAgent(agent: CircleOfficeAgent): AssignableAgent {
  const extended = parseAgentExtendedConfig(agent.currentGoal);
  return {
    id: agent.id,
    name: agent.name,
    status: agent.status || 'idle',
    provider: agent.provider,
    ownerId: agent.ownerId,
    isOwn: agent.isOwn === true,
    color: agent.color,
    owner_display_name: agent.ownerDisplayName,
    current_task: agent.currentTask || null,
    circle_id: agent.circleId,
    spirit: agent.spirit || null,
    model: agent.model_name || extended?.modelPreference || null,
    // A public Office UUID is not an OpenSwan provider session identity. Own
    // OpenSwan rows resolve through their owner-private binding at dispatch.
    sessionKey: null,
    connectionId: null,
    gatewayUrl: agent.gatewayUrl || null,
    source: 'db',
  };
}

function toAssignableSessionAgent(agent: OfficeAgent, circleId: string): AssignableAgent {
  return {
    id: agent.id,
    name: agent.name,
    status: agent.status,
    provider: agent.providerType,
    color: agent.color,
    owner_display_name: agent.connectionName,
    current_task: agent.activity || null,
    circle_id: circleId,
    spirit: agent.spirit || null,
    model: agent.model || null,
    sessionKey: agent.sessionKey || null,
    connectionId: agent.connectionId || null,
    source: 'openswan-session',
  };
}

function buildAssignableAgentSubjectMetadata(agent: AssignableAgent): AgentRuntimeSubjectMetadata {
  return buildAgentRuntimeSubject({
    id: agent.id,
    name: agent.name,
    sessionKey: agent.sessionKey || undefined,
    providerType: agent.provider as any,
    spirit: agent.spirit || undefined,
  }, {
    dbAgentId: isUuidLike(agent.id) ? agent.id : null,
  }).metadata;
}
