function getFallbackSpiritIdForSessionProfile(profile: SessionCodingProfile): string {
  switch (profile) {
    case 'auto':
      return 'sr-engineer';
    case 'review':
      return 'code-reviewer';
    case 'debug':
      return 'qa-engineer';
    case 'architect':
      return 'architect';
    case 'senior':
    default:
      return 'sr-engineer';
  }
}

