function FloatingEmoji({ emoji, onComplete }: { emoji: string; onComplete: () => void }) {
  const floatAnim = useRef(new Animated.Value(0)).current;
  const fadeAnim = useRef(new Animated.Value(1)).current;

  useEffect(() => {
    Animated.parallel([
      Animated.timing(floatAnim, {
        toValue: -80,
        duration: 2000,
        useNativeDriver: true,
      }),
      Animated.sequence([
        Animated.delay(1200),
        Animated.timing(fadeAnim, {
          toValue: 0,
          duration: 800,
          useNativeDriver: true,
        }),
      ]),
    ]).start(onComplete);
  }, []);

  return (
    <Animated.View
      style={[
        styles.floatingEmoji,
        {
          transform: [{ translateY: floatAnim }],
          opacity: fadeAnim,
        },
      ]}
    >
      <Text style={styles.floatingEmojiText}>{emoji}</Text>
    </Animated.View>
  );
}

function ParticleEffect({ x, y, color, onComplete }: { x: number; y: number; color: string; onComplete: () => void }) {
  const particlesRef = useRef<Animated.Value[]>([]);
  if (particlesRef.current.length === 0) {
    particlesRef.current = Array.from({ length: 8 }, () => new Animated.Value(0));
  }
  const particles = particlesRef.current;
  const fadeAnim = useRef(new Animated.Value(1)).current;
  const onCompleteRef = useRef(onComplete);
  onCompleteRef.current = onComplete;

  useEffect(() => {
    const animations = particles.map((anim, i) => {
      const angle = (i / particles.length) * Math.PI * 2;
      const distance = 30;
      return Animated.timing(anim, {
        toValue: distance,
        duration: 1000,
        useNativeDriver: true,
      });
    });

    const animation = Animated.parallel([
      ...animations,
      Animated.sequence([
        Animated.delay(500),
        Animated.timing(fadeAnim, {
          toValue: 0,
          duration: 500,
          useNativeDriver: true,
        }),
      ]),
    ]);
    animation.start(({ finished }) => {
      if (finished) onCompleteRef.current();
    });
    return () => animation.stop();
  }, [fadeAnim, particles]);

  return (
    <View style={[styles.particleContainer, { top: y, left: x }]}>
      {particles.map((anim, i) => {
        const angle = (i / particles.length) * Math.PI * 2;
        return (
          <Animated.View
            key={i}
            style={[
              styles.particle,
              { backgroundColor: color },
              {
                transform: [
                  { translateX: Animated.multiply(anim, Math.cos(angle)) },
                  { translateY: Animated.multiply(anim, Math.sin(angle)) },
                ],
                opacity: fadeAnim,
              },
            ]}
          />
        );
      })}
    </View>
  );
}

